import{_ as a,o as s,c as e,a2 as i}from"./chunks/framework.BZO4qERu.js";const c=JSON.parse('{"title":"内置记忆","description":"","frontmatter":{},"headers":[],"relativePath":"zh/integrations/providers/memory/builtin.md","filePath":"zh/integrations/providers/memory/builtin.md","lastUpdated":1788855895000}'),r={name:"zh/integrations/providers/memory/builtin.md"};function o(n,t,l,d,h,p){return s(),e("div",null,[...t[0]||(t[0]=[i(`<h1 id="内置记忆" tabindex="-1">内置记忆 <a class="header-anchor" href="#内置记忆" aria-label="Permalink to &quot;内置记忆&quot;">​</a></h1><p>自带默认记忆后端，接 Memoh 的抽取/检索流程，支持：</p><ul><li>从对话里抽记忆</li><li>聊天时语义检索</li><li>手建、手改</li><li>记忆压缩、整库重建</li></ul><hr><h2 id="工作方式" tabindex="-1">工作方式 <a class="header-anchor" href="#工作方式" aria-label="Permalink to &quot;工作方式&quot;">​</a></h2><p>内置提供方运行在 <strong>graph</strong> 模式：记忆节点与边存放在 PostgreSQL 中作为唯一真源，并派生出一份 Markdown 视图（机器人工作区里的 <code>memory/</code> bundle 和 <code>MEMORY.md</code>）供 Agent 读写。</p><p>语义检索是可选的加层：</p><table tabindex="0"><thead><tr><th>层</th><th>存储</th><th>要啥</th><th>提供什么</th></tr></thead><tbody><tr><td><strong>Graph</strong>（始终开启）</td><td>PostgreSQL 记忆节点/边</td><td>只要主库</td><td>结构化召回、记忆间关系、压缩、重建</td></tr><tr><td><strong>语义索引</strong>（可选）</td><td><code>pgvector</code> 数据库</td><td>Compose 栈里的 <code>[pgvector]</code> 库 <strong>加上</strong> 在提供方里选好 embedding 模型</td><td>对记忆节点做向量相似度检索</td></tr></tbody></table><p>没选 embedding 模型，或没配 <code>pgvector</code>，提供方照样以纯 graph 模式工作，只是跳过语义检索。</p><hr><h2 id="建一个" tabindex="-1">建一个 <a class="header-anchor" href="#建一个" aria-label="Permalink to &quot;建一个&quot;">​</a></h2><ol><li><strong>Memory Providers</strong>。</li><li><strong>Add Memory Provider</strong>。</li><li><strong>Name</strong>、<strong>Provider Type</strong> 选 <code>builtin</code>。</li><li><strong>Create</strong>。</li></ol><hr><h2 id="配置" tabindex="-1">配置 <a class="header-anchor" href="#配置" aria-label="Permalink to &quot;配置&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>说明</th></tr></thead><tbody><tr><td><strong>Embedding Model</strong></td><td>可选。来自某个 LLM 提供方的 embedding 模型。选了（且 <code>pgvector</code> 可用）就会给记忆节点做向量并开启语义检索；留空即纯 graph 模式。</td></tr></tbody></table><p><strong>Edit</strong>、<strong>Delete</strong> 如常。</p><hr><h2 id="依赖" tabindex="-1">依赖 <a class="header-anchor" href="#依赖" aria-label="Permalink to &quot;依赖&quot;">​</a></h2><h3 id="纯-graph" tabindex="-1">纯 graph <a class="header-anchor" href="#纯-graph" aria-label="Permalink to &quot;纯 graph&quot;">​</a></h3><p>除主 PostgreSQL 外无额外依赖。</p><h3 id="语义索引" tabindex="-1">语义索引 <a class="header-anchor" href="#语义索引" aria-label="Permalink to &quot;语义索引&quot;">​</a></h3><p>默认 Docker Compose 栈已经带了 <code>pgvector</code> 服务，<code>config.toml</code> 里也有对应段：</p><div class="language-toml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">toml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pgvector</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">enabled = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">true</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">host = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pgvector&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">port = </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">5432</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">user = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">password = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh123&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">database = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;memoh_vector&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sslmode = </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;disable&quot;</span></span></code></pre></div><p>然后在提供方里选一个 <strong>Embedding Model</strong>。向量由所选 LLM 提供方（OpenAI、Gemini、Ollama……）生成，因此该提供方需要有 embedding 模型可用。</p><hr><h2 id="绑到机器人" tabindex="-1">绑到机器人 <a class="header-anchor" href="#绑到机器人" aria-label="Permalink to &quot;绑到机器人&quot;">​</a></h2><ol><li><strong>Bots</strong> → 机器人</li><li><strong>General</strong> → <strong>Memory Provider</strong></li><li>保存</li></ol><p>若未选，运行层面不会用这条提供方。</p><hr><h2 id="配好之后" tabindex="-1">配好之后 <a class="header-anchor" href="#配好之后" aria-label="Permalink to &quot;配好之后&quot;">​</a></h2><p>在机器人的 <strong>Memory</strong> tab 里管理具体记忆：</p><ul><li>手动新建</li><li>从对话抽取</li><li>搜索、编辑、删除</li><li>压缩或重建记忆库</li></ul><p>日常操作见 <a href="/zh/guides/memory.html">记忆管理</a>。</p>`,33)])])}const k=a(r,[["render",o]]);export{c as __pageData,k as default};
